import pytest

from vlan_utils import parse_vlan_range


def test_single_vlan():
    assert parse_vlan_range("10") == [10]


def test_list_and_range():
    assert parse_vlan_range("10,20-22") == [10, 20, 21, 22]


def test_rejects_reserved_vlan():
    with pytest.raises(ValueError):
        parse_vlan_range("4095")

def parse_vlan_range(text):
    """Turn a string such as '10,20-22' into a sorted list of VLAN IDs."""
    vlans = set()
    for part in text.split(","):
        part = part.strip()
        if "-" in part:
            start, end = (int(x) for x in part.split("-"))
            vlans.update(range(start, end + 1))
        else:
            vlans.add(int(part))
    for vlan in vlans:
        if not 1 <= vlan <= 4094:
            raise ValueError(f"VLAN {vlan} is outside 1-4094")
    return sorted(vlans)

